type Line { done: List[Str], current: Str }

fn pieces(word: Str, width: Int) -> List[Str] {
  if word.len() <= width {
    return [word]
  }
  let rest = pieces(word.slice(width, word.len()), width)
  return rest.insert(0, word.slice(0, width))
}

fn add_word(st: Line, word: Str, width: Int) -> Line {
  if st.current.is_empty() {
    return Line { done: st.done, current: word }
  }
  if st.current.len() + 1 + word.len() <= width {
    return Line { done: st.done, current: st.current + " " + word }
  }
  return Line { done: st.done.push(st.current), current: word }
}

fn finish(st: Line) -> List[Str] {
  if st.current.is_empty() {
    return st.done
  }
  return st.done.push(st.current)
}

pub fn wrap(text: Str, width: Int) -> List[Str] {
  let words = text.split(" ").filter(fn(w) => not w.is_empty()).flat_map(fn(w) => pieces(w, width))
  let no_lines: List[Str] = []
  let start = Line { done: no_lines, current: "" }
  let end_state = words.fold(start, fn(st, w) => add_word(st, w, width))
  return finish(end_state)
}
